import type {SelectOption, SelectOptionGroup} from '@gravity-ui/uikit';

export function getValueOption(
    options: (SelectOption | SelectOptionGroup)[],
    value: string,
): SelectOption | undefined {
    for (const option of options ?? []) {
        if ('options' in option) {
            const result = getValueOption(option.options ?? [], value);

            if (result) {
                return result;
            }
        } else if ('value' in option && option.value === value) {
            return option;
        }
    }

    return undefined;
}
